package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
)

// defaultConfig is the config template written to ~/.vidify/config.yaml
// by `vidify init`. Keeping it here (not in configs/) means the shipped
// binary is fully self-contained.
const defaultConfig = `# Vidify configuration file
# Generated by: vidify init
# Loaded automatically from: ~/.vidify/config.yaml
#
# Priority: CLI flags > VIDIFY_* env vars > this file > built-in defaults.

# ============================================================
# Processing parameters
# ============================================================

# Whisper model: tiny | base | small | medium | large
model: medium

# Language for transcription: "auto" for auto-detect, or BCP-47 code (en, zh, ja)
language: auto

# Translate non-English speech to English
translate: false

# Background image path (empty = built-in default)
bg-image: ""

# Output directory (empty = current directory)
output: ""

# ============================================================
# Logging configuration
# ============================================================

log:
  # Directory for log files. Empty = ~/.vidify/logs (created automatically).
  dir: ""

  # Minimum log level: debug | info | warn | error
  level: info

  # Write a JSON log file alongside the console output.
  # Set to false for pipe-friendly or CI environments.
  to-file: true

  # Number of old rotated log files to retain.
  max-backups: 7

  # Maximum age in days before a log file is deleted.
  max-age: 30

  # Maximum size in megabytes before the log file is rotated.
  max-size: 100

# ============================================================
# Advanced: binary paths (leave empty to auto-detect)
# ============================================================

# whisper-bin: ""

# Directory containing Whisper .bin model files.
# Empty = ~/.vidify/models (created automatically).
# whisper-model-dir: ""

# ffmpeg-bin: ""
`

// initCmd creates the default config file at ~/.vidify/config.yaml.
// It is the recommended first step for new users who want to customise
// Vidify's behaviour beyond what CLI flags expose.
var initCmd = &cobra.Command{
	Use:   "init",
	Short: "Create the default config file and app directories under ~/.vidify/",
	Long: `Create the Vidify application directory at ~/.vidify/ and write a
default configuration file at ~/.vidify/config.yaml.

The following directories are created:

  ~/.vidify/
  ├── config.yaml    ← edit to change defaults
  ├── logs/          ← log files written here automatically
  ├── models/        ← place Whisper .bin model files here
  ├── assets/        ← built-in assets (future)
  └── backgrounds/   ← custom background images (future)

The config file is pre-filled with every supported option and its built-in
default value. Edit it to avoid repeating flags on every invocation.

If the config file already exists, this command does nothing unless --force
is given. Directories are always created (idempotent).`,
	RunE: runInit,
}

func init() {
	initCmd.Flags().Bool("force", false, "overwrite an existing config file")
	rootCmd.AddCommand(initCmd)
}

func runInit(cmd *cobra.Command, _ []string) error {
	force, _ := cmd.Flags().GetBool("force")

	home, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("cannot determine home directory: %w", err)
	}

	vidifyDir := filepath.Join(home, ".vidify")

	// Create the root app directory and all standard subdirectories.
	// We do this inline here — adapter/cli does not import the appdir package.
	subdirs := []string{"logs", "models", "assets", "backgrounds"}
	if err := os.MkdirAll(vidifyDir, 0o755); err != nil {
		return fmt.Errorf("cannot create app directory %s: %w", vidifyDir, err)
	}
	for _, sub := range subdirs {
		subPath := filepath.Join(vidifyDir, sub)
		if err := os.MkdirAll(subPath, 0o755); err != nil {
			// Non-fatal: warn and continue so the config file is still written.
			fmt.Fprintf(cmd.ErrOrStderr(), "WARN: cannot create %s: %v\n", subPath, err)
		}
	}

	dest := filepath.Join(vidifyDir, "config.yaml")

	if _, err := os.Stat(dest); err == nil && !force {
		fmt.Fprintf(cmd.OutOrStdout(),
			"Config file already exists: %s\nUse --force to overwrite.\n", dest)
		return nil
	}

	if err := os.WriteFile(dest, []byte(defaultConfig), 0o644); err != nil {
		return fmt.Errorf("cannot write config file: %w", err)
	}

	out := cmd.OutOrStdout()
	fmt.Fprintf(out, "Vidify initialized at %s\n\n", vidifyDir)
	fmt.Fprintf(out, "  %s/\n", vidifyDir)
	fmt.Fprintf(out, "  ├── config.yaml    ← edit to change defaults\n")
	fmt.Fprintf(out, "  ├── logs/          ← log files written here automatically\n")
	fmt.Fprintf(out, "  ├── models/        ← place Whisper .bin model files here\n")
	fmt.Fprintf(out, "  ├── assets/        ← built-in assets (future)\n")
	fmt.Fprintf(out, "  └── backgrounds/   ← custom background images (future)\n")
	fmt.Fprintf(out, "\nDownload Whisper models from:\n  https://huggingface.co/ggerganov/whisper.cpp\n")
	return nil
}
